// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(role != bytes32(0));
        vm.assume(account != address(0) && account != address(this));
        // Grant PROPOSER_ROLE to account so cancel can be called
        c.grantRole(c.PROPOSER_ROLE(), account);
        vm.prank(account);
        bytes32 id = keccak256(abi.encode(account, role));
        // Schedule an operation so cancel can work
        address[] memory targets = new address[](1);
        targets[0] = address(0);
        uint256[] memory values = new uint256[](1);
        values[0] = 0;
        bytes[] memory datas = new bytes[](1);
        datas[0] = "";
        vm.warp(block.timestamp + 1);
        c.scheduleBatch(targets, values, datas, bytes32(0), bytes32(0), 1);
        // Now call cancel as the proposer
        c.cancel(id);
        // Assert that supportsInterface(IERC165.interfaceId) is always true
        assertTrue(c.supportsInterface(type(IERC165).interfaceId));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The reference contract must support both IAccessControl and IERC165
        // The mutant only supports IERC165
        bool refSupportsIERC165 = c.supportsInterface(type(IERC165).interfaceId);
        bool refSupportsIAccessControl = c.supportsInterface(type(IAccessControl).interfaceId);

        // For any interface ID, the rule is: if the ID is IERC165 or IAccessControl, supportsInterface returns true
        // This is a general rule that the reference satisfies and the mutant breaks.
        bool isIERC165 = interfaceId == type(IERC165).interfaceId;
        bool isIAccessControl = interfaceId == type(IAccessControl).interfaceId;

        // If the interface ID is either IERC165 or IAccessControl, supportsInterface must return true.
        // If it's neither, no requirement (can be true or false).
        assertTrue(!(isIERC165 || isIAccessControl) || c.supportsInterface(interfaceId));
    }

    function testRegression_supportsInterfaceIAccessControl() public {
        // Specific regression: IAccessControl interface must be supported
        assertTrue(c.supportsInterface(type(IAccessControl).interfaceId));
    }
}

