pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // We assume the interface ID is not 0xffffffff to avoid wildcard overlap
        vm.assume(interfaceId != 0xffffffff);
        bool supportsResult = c.supportsInterface(interfaceId);
        // The general rule: for any interface ID that is not the ERC165 or IAccessControl interfaces,
        // supportsInterface should return false.
        bool expected = (interfaceId == type(IERC165).interfaceId || interfaceId == type(IAccessControl).interfaceId);
        assertTrue(supportsResult == expected, "supportsInterface mismatch");
    }
}

