pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        delay = bound(delay, c.getMinDelay(), 1000000);
        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        // Warp to make it ready
        vm.warp(block.timestamp + delay);
        // Attempt to cancel; it should revert because the operation is ready
        bool reverted;
        try c.cancel(id) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted, "cancel should revert when operation is ready");
    }
}

