        bool isPending = c.isOperationPending(id);
        if (isPending) {
            c.cancel(id);
        } else {
            try c.cancel(id) {
                // cancel succeeded, which would only be possible if isPending were true
                assertTrue(false);
            } catch {
                // expected revert
                assertTrue(true);
            }
        }
    }
}

