pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role) public {
        vm.assume(role != bytes32(0));

        // Get the admin role before any operation
        bytes32 adminBefore = c.getRoleAdmin(role);

        // Schedule and execute a dummy operation to allow cancel to be called
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), role);

        // Only proceed if we can cancel (operation must be pending)
        // We use role as salt to make the id unique per fuzz run
        c.schedule(address(0), 0, "", bytes32(0), role, 1 days);

