pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role1, bytes32 role2) public {
        vm.assume(role1 != role2);
        // For the reference contract, getRoleAdmin should return the admin role set for the given role.
        // Since the admin role for any role is set via _setRoleAdmin, the expected invariant is:
        // If a role is its own admin (like TIMELOCK_ADMIN_ROLE), then getRoleAdmin(role) == role.
        // But more generally, we can check consistency: getRoleAdmin(role) should equal the admin role
        // that was set during construction. For roles that are not explicitly set, the default admin is 0x00.
        //
        // We can test the behavior by checking that getRoleAdmin returns a value that is consistent with
        // the expected admin role for any role. Since we cannot directly read the private _roles mapping,
        // we use a public method: hasRole(getRoleAdmin(role), address(this)) should be true for any role
        // because the admin of any role is either 0x00 (DEFAULT_ADMIN_ROLE) which is its own admin,
        // or the role itself (if it's TIMELOCK_ADMIN_ROLE) which is also its own admin, or TIMELOCK_ADMIN_ROLE.
        // In all cases, the admin role has itself as admin (since self-admin is set), so hasRole(admin, address(this)) should always be true.
        // But wait: hasRole(0x00, address(this)) is true because DEFAULT_ADMIN_ROLE is granted to address(this)? Actually in constructor
        // only TIMELOCK_ADMIN_ROLE is granted to address(this) and to msg.sender. But DEFAULT_ADMIN_ROLE (0x00) is never granted.
        // So hasRole(0x00, address(this)) is false. That breaks this property.
        //
        // Alternative: Since we know all roles have admin either TIMELOCK_ADMIN_ROLE or themselves (for TIMELOCK_ADMIN_ROLE),
        // and TIMELOCK_ADMIN_ROLE is granted to address(this), we can check:
        // hasRole(c.TIMELOCK_ADMIN_ROLE(), c.getRoleAdmin(role)) should always be true because the admin of any role
        // is either TIMELOCK_ADMIN_ROLE or the role itself if it is TIMELOCK_ADMIN_ROLE. But for DEFAULT_ADMIN_ROLE (0x00),
        // its admin is itself (0x00) which is not TIMELOCK_ADMIN_ROLE, so hasRole(TIMELOCK_ADMIN_ROLE, 0x00) is false.
        // So still not universal.
        //
        // Instead, we can use a simpler invariant: For the reference contract, getRoleAdmin is bijective over a fixed set?
        // Actually the simplest invariant: The bug changes getRoleAdmin to return keccak256(abi.encode(role)).
        // In the reference, getRoleAdmin is deterministic and based on stored admin roles.
        // We can check: For any role, getRoleAdmin(role) should be either 0x00 or keccak256("TIMELOCK_ADMIN_ROLE")? No.
        //
        // Let's use a direct approach: In the reference, getRoleAdmin(role) returns the stored admin role.
        // The bug returns keccak256(abi.encode(role)). These differ for any role with a stored admin role != keccak256(abi.encode(role)).
        // But we need a general rule that holds for all inputs in the reference and fails for the bug.
        // One such rule: getRoleAdmin(role) depends only on role, not on msg.sender, and we can verify that
        // calling getRoleAdmin twice with the same role returns the same value.
        // That holds for both reference and bug? Actually bug also returns deterministic value based on role.
        // So both are deterministic. Not useful.
        //
        // Another idea: In the reference, getRoleAdmin(role) is always equal to either 0x00 (for roles with no explicit admin)
        // or the admin role explicitly set. But for TIMELOCK_ADMIN_ROLE, its admin is itself. So we can check:
        // getRoleAdmin(role) == role OR getRoleAdmin(role) == 0x00 (for default) OR getRoleAdmin(role) == TIMELOCK_ADMIN_ROLE.
        // But for the bug, getRoleAdmin returns a hash that is never equal to any of these fixed values (with high probability).
        // So the rule: getRoleAdmin(role) is either 0x00, role, or c.TIMELOCK_ADMIN_ROLE().
        // But is that true for all possible roles in the reference? The constructor only sets admin for three roles,
        // and other roles default to 0x00. So yes: for any role, admin is either 0x00 (default), itself (for TIMELOCK_ADMIN_ROLE),
        // or TIMELOCK_ADMIN_ROLE (for PROPOSER_ROLE and EXECUTOR_ROLE). So the condition holds.
        // For the bug, keccak256(abi.encode(role)) is almost never equal to any of those three values.
        bytes32 admin = c.getRoleAdmin(role1);
        bool condition = (admin == bytes32(0) || admin == role1 || admin == c.TIMELOCK_ADMIN_ROLE());
        assertTrue(condition, "getRoleAdmin should return 0x00, the role itself, or TIMELOCK_ADMIN_ROLE");
    }
}

