pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 timestamp) public {
        vm.assume(timestamp > 1);
        // We cannot directly set _timestamps[id] because it's private, so we must drive the contract to set it.
        // The only way to set a timestamp > 1 is to schedule an operation with a delay.
        // Use schedule to set the timestamp, then check isOperationDone
        // We need a proposer role to schedule. The deployer has DEFAULT_ADMIN_ROLE which can grant PROPOSER_ROLE.
        // But we already have the role via the constructor? Actually the deployer is address(this) in setUp, so we can grant ourselves the proposer role.
        // To simplify, we assume the test contract is the default admin and can grant itself proposer role.
        // We'll just schedule a dummy operation with sufficient delay.
        // The id will be derived from the parameters; we can bound timestamp to be > block.timestamp + minDelay to ensure it's scheduled.
        // But the test must be general: we need an id such that getTimestamp(id) > 1.
        // We'll just use the id from a scheduled operation and then verify.
        // However, the rule is: for any operation id, isOperationDone returns false when getTimestamp > 1.
        // We can test this by scheduling an operation (which sets timestamp > 1) and then checking isOperationDone is false.
        // Since we can't directly set an arbitrary id, we use the scheduled operation's id.
        // Use a dummy target and data to create an operation.
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(12345));
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);
        // Ensure the operation hasn't been scheduled yet
        vm.assume(!c.isOperation(opId));
        // Grant PROPOSER_ROLE to this contract
        bytes32 proposerRole = c.PROPOSER_ROLE();
        c.grantRole(proposerRole, address(this));
        // Schedule with a delay that makes timestamp > 1
        uint256 delay = 1000;
        c.schedule(target, value, data, predecessor, salt, delay);
        // Now check: isOperationDone should be false because getTimestamp(opId) is block.timestamp + delay > 1
        assertTrue(!c.isOperationDone(opId), "isOperationDone should be false for a pending operation");
    }
}

